// Assumed runtime API from @jinx-ui/react: Switch {checked,onChange}, Slider {value,min,max,step,onChange}, Select {value,onChange,options}.
import { useCallback, useId, useState } from 'react';
import { Select, Slider, Switch } from '@jinx-ui/react';

export type AppearanceTheme = 'brutal' | 'glass' | 'minimal';

export interface AppearanceValue {
  theme: AppearanceTheme;
  scale: number;
  dense: boolean;
  fontFamily: string;
}

export interface AppearanceSettingsProps {
  defaultValue?: Partial<AppearanceValue>;
  onChange?: (value: AppearanceValue) => void;
}

const THEMES: ReadonlyArray<{ id: AppearanceTheme; label: string }> = [
  { id: 'brutal', label: 'Brutal' },
  { id: 'glass', label: 'Glass' },
  { id: 'minimal', label: 'Minimal' },
];

const FONTS = [
  { value: 'system', label: 'Системный' },
  { value: 'grotesk', label: 'Grotesk' },
  { value: 'mono', label: 'Mono' },
];

const MIN_SCALE = 80;
const MAX_SCALE = 140;

export default function AppearanceSettings({ defaultValue, onChange }: AppearanceSettingsProps) {
  const [value, setValue] = useState<AppearanceValue>({
    theme: 'brutal',
    scale: 100,
    dense: false,
    fontFamily: 'system',
    ...defaultValue,
  });

  const scaleId = useId();
  const denseId = useId();
  const fontId = useId();
  const themeLabelId = useId();

  const update = useCallback(
    (patch: Partial<AppearanceValue>) => {
      setValue((prev) => {
        const next = { ...prev, ...patch };
        onChange?.(next);
        return next;
      });
    },
    [onChange],
  );

  const onThemeKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    const delta = event.key === 'ArrowRight' || event.key === 'ArrowDown' ? 1 : event.key === 'ArrowLeft' || event.key === 'ArrowUp' ? -1 : 0;
    if (delta === 0) return;
    event.preventDefault();
    const index = THEMES.findIndex((theme) => theme.id === value.theme);
    const next = THEMES[(index + delta + THEMES.length) % THEMES.length];
    update({ theme: next.id });
  };

  const activeTheme = THEMES.find((theme) => theme.id === value.theme);

  return (
    <section className="jx-card jx-stack" style={{ gap: 'var(--jx-space-4)' }}>
      <header className="jx-card__header jx-row" style={{ justifyContent: 'space-between', alignItems: 'center', gap: 'var(--jx-space-3)' }}>
        <h2 className="jx-heading">Внешний вид</h2>
        <span className="jx-badge">{activeTheme?.label}</span>
      </header>

      <div className="jx-field jx-stack" style={{ gap: 'var(--jx-space-2)' }}>
        <span className="jx-label" id={themeLabelId}>Тема</span>
        <div className="jx-segmented" role="radiogroup" aria-labelledby={themeLabelId} onKeyDown={onThemeKeyDown}>
          {THEMES.map((theme) => {
            const selected = theme.id === value.theme;
            return (
              <button
                key={theme.id}
                type="button"
                role="radio"
                aria-checked={selected}
                tabIndex={selected ? 0 : -1}
                className={selected ? 'jx-segmented__item is-active' : 'jx-segmented__item'}
                onClick={() => update({ theme: theme.id })}
              >
                {theme.label}
              </button>
            );
          })}
        </div>
      </div>

      <div className="jx-field jx-stack" style={{ gap: 'var(--jx-space-2)' }}>
        <div className="jx-row" style={{ justifyContent: 'space-between', alignItems: 'baseline' }}>
          <label className="jx-label" htmlFor={scaleId}>Масштаб интерфейса</label>
          <output className="jx-hint" htmlFor={scaleId}>{value.scale}%</output>
        </div>
        <Slider
          id={scaleId}
          min={MIN_SCALE}
          max={MAX_SCALE}
          step={5}
          value={value.scale}
          onChange={(scale: number) => update({ scale })}
        />
      </div>

      <div className="jx-field jx-row" style={{ justifyContent: 'space-between', alignItems: 'center', gap: 'var(--jx-space-3)' }}>
        <label className="jx-label" htmlFor={denseId}>Плотная вёрстка</label>
        <Switch id={denseId} checked={value.dense} onChange={(dense: boolean) => update({ dense })} />
      </div>

      <hr className="jx-divider" />

      <div className="jx-stack" style={{ gap: 'var(--jx-space-3)' }}>
        <h3 className="jx-heading">Ещё</h3>
        <div className="jx-field jx-stack" style={{ gap: 'var(--jx-space-2)' }}>
          <label className="jx-label" htmlFor={fontId}>Шрифт</label>
          <Select
            id={fontId}
            value={value.fontFamily}
            options={FONTS}
            onChange={(fontFamily: string) => update({ fontFamily })}
          />
        </div>
      </div>
    </section>
  );
}

